package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// Page is the site's changelog page, relative to the repository root.
const Page = "website/src/content/docs/changelog.md"

const pageHead = `---
title: Changelog
description: "What changed in each apic release: new commands, flags and MCP tools, changes to the --json contract, and fixes, newest first."
---

<!-- Generated by scripts/changelog from CHANGELOG.md at the repository
root; edit that file and run task docs:changelog. -->

`

// blankRuns is three or more newlines, which the page folds into one blank
// line where a section was taken out.
var blankRuns = regexp.MustCompile(`\n{3,}`)

// Released names the newest published release, the one the site's page
// and pins follow. A release pull request dates its section and leaves
// this alone, so the site does not name a version before its archives
// exist; release.yml's docs job moves it with -publish once goreleaser has
// published, and commits what that regenerates.
const Released = "website/released-version"

// published reads Released: a version with a dated section in changelog.
func published(read reader, changelog string) (string, error) {
	text, err := read(Released)
	if err != nil {
		return "", err
	}
	v := strings.TrimSpace(text)
	if !semver.MatchString(v) {
		return "", fmt.Errorf("%s holds %q, not a version like 0.2.0", Released, v)
	}
	if _, err := Section(changelog, v); err != nil {
		return "", fmt.Errorf("%s names %s: %w", Released, v, err)
	}
	return v, nil
}

// SitePage renders CHANGELOG.md as the site's page for the published
// release: the file's own title gives way to the page's front matter, and
// Unreleased and every section above published are left out with their
// link references. The page lists releases a reader can install, so
// neither a line under Unreleased nor a release pull request's newly dated
// section changes it; publishing does.
func SitePage(changelog, published string) string {
	text := changelog
	if strings.HasPrefix(text, "# ") {
		_, text, _ = strings.Cut(text, "\n")
	}
	lines := scan(text)
	hidden := map[string]bool{}
	for _, l := range lines {
		if l.heading != nil && (l.heading[1] == unreleased || compareVersions(version(l.heading), published) > 0) {
			hidden[l.heading[1]] = true
			hidden[l.heading[2]] = true
		}
	}
	var kept []string
	skipping := false
	for _, l := range lines {
		if l.h2 || l.trailing {
			skipping = l.heading != nil && hidden[l.heading[1]]
		}
		if skipping || (l.ref != nil && hidden[l.ref[1]]) {
			continue
		}
		kept = append(kept, l.text)
	}
	text = blankRuns.ReplaceAllString(strings.Join(kept, "\n"), "\n\n")
	return pageHead + strings.TrimSpace(text) + "\n"
}

// A Pin is one place the docs name the current release: the phrase as it
// reads, with {v} for the version (0.2.0) and {minor} for its minor (0.2).
// The phrase is matched with any version in those places and the rest
// taken literally, so a dot in a hostname is a dot. Every pin must match at
// least once, so a reworded line fails the test instead of keeping an old
// version quietly.
type Pin struct {
	File string // relative to the repository root
	Text string // the phrase, with {v} and {minor}
	re   *regexp.Regexp
}

// Patterns for a version in a pin: a full version, prerelease included so
// a pin rewritten from one cannot keep its suffix, and a minor. semver in
// main.go is the same grammar, anchored.
const (
	ver   = `\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?`
	minor = `\d+\.\d+`
)

var placeholder = regexp.MustCompile(`\{v\}|\{minor\}`)

func pin(file, text string) Pin {
	var pattern strings.Builder
	last := 0
	for _, loc := range placeholder.FindAllStringIndex(text, -1) {
		pattern.WriteString(regexp.QuoteMeta(text[last:loc[0]]))
		if text[loc[0]:loc[1]] == "{v}" {
			pattern.WriteString(ver)
		} else {
			pattern.WriteString(minor)
		}
		last = loc[1]
	}
	pattern.WriteString(regexp.QuoteMeta(text[last:]))
	return Pin{File: file, Text: text, re: regexp.MustCompile(pattern.String())}
}

// Pins are the places the docs name the current release. A new one goes
// here, not into the page by hand.
var Pins = []Pin{
	pin("website/src/content/docs/getting-started.mdx", "V={v}   # the release, without the v"),
	pin("website/src/content/docs/getting-started.mdx", "with: version:\nv{v}` to pin one"),
	pin("website/src/content/docs/cookbook.md", "`with: version: v{v}`"),
	pin("website/src/content/docs/cookbook.md", "tagged with the version (`{v}` and `v{v}`), the minor (`v{minor}`)"),
	pin("website/src/content/docs/cookbook.md", "COPY --from=ghcr.io/hungovercoders/apic:v{minor} "),
	pin("website/src/content/docs/verifying.md", "VERSION=v{v}\n"),
	pin("website/src/content/docs/verifying.md", "ghcr.io/hungovercoders/apic:{v} "),
	pin("website/src/content/docs/verifying.md", "apic_{v}_linux_amd64.tar.gz.sbom.json"),
	pin("website/src/content/docs/learn/01-first-request.md", "apic v{v} · "),
	pin("website/src/content/docs/learn/01-first-request.md", `"version": "v{v}"`),
	pin("website/src/content/docs/learn/04-assertions.md", `"version": "v{v}"`),
	pin("website/src/content/docs/learn/08-ci.md", "version: v{v}"),
	pin("website/src/content/docs/learn/09-import-export.md", `"version": "v{v}"`),
	pin("setup-apic/README.md", `version: v{v} # or "latest"`),
}

var minorPrefix = regexp.MustCompile(`^` + minor)

// minorOf is a version's major.minor: 0.2 for 0.2.0 and for 0.2.0-rc.1.
func minorOf(version string) string {
	return minorPrefix.FindString(version)
}

// A reader returns a file of the repository by its path from the root: as
// it is on disk, or as it was at a commit (fromGit, in release.go), so the
// release check can be run against history as well as the working tree.
// A file that does not exist is an error satisfying os.IsNotExist.
type reader func(path string) (string, error)

func fromDisk(root string) reader {
	return func(path string) (string, error) {
		data, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(path))) //nolint:gosec // a docs page in the repository
		return string(data), err
	}
}

// pinned returns a file's text with every pin in it naming version.
func pinned(read reader, file, version string) (before, after string, err error) {
	before, err = read(file)
	if err != nil {
		return "", "", err
	}
	after = before
	text := strings.NewReplacer("{v}", version, "{minor}", minorOf(version))
	for _, p := range Pins {
		if p.File != file {
			continue
		}
		if !p.re.MatchString(after) {
			return "", "", fmt.Errorf("%s: no match for the pin %q; reword it in Pins (scripts/changelog/site.go) rather than in the page", file, p.Text)
		}
		after = p.re.ReplaceAllLiteralString(after, text.Replace(p.Text))
	}
	return before, after, nil
}

// files is every file the site's changelog and the pins touch, the page
// first, each once.
func files() []string {
	out := []string{Page}
	seen := map[string]bool{Page: true}
	for _, p := range Pins {
		if !seen[p.File] {
			seen[p.File] = true
			out = append(out, p.File)
		}
	}
	return out
}

// A change is one file as it is and as the changelog says it should be.
type change struct{ file, current, want string }

// changes returns every file the changelog governs with what it should
// hold for the published release: the site's page, and each pinned page
// naming the newest stable release at or below it.
func changes(read reader, changelog string) ([]change, error) {
	pub, err := published(read, changelog)
	if err != nil {
		return nil, err
	}
	stable, err := Stable(changelog, pub)
	if err != nil {
		return nil, err
	}
	var out []change
	for _, f := range files() {
		if f == Page {
			current, err := read(Page)
			if err != nil && !os.IsNotExist(err) {
				return nil, err
			}
			out = append(out, change{f, current, SitePage(changelog, pub)})
			continue
		}
		before, after, err := pinned(read, f, stable)
		if err != nil {
			return nil, err
		}
		out = append(out, change{f, before, after})
	}
	return out, nil
}

// Stale lists the files that do not match the changelog yet.
func Stale(read reader, changelog string) ([]string, error) {
	all, err := changes(read, changelog)
	if err != nil {
		return nil, err
	}
	var stale []string
	for _, c := range all {
		if c.current != c.want {
			stale = append(stale, c.file)
		}
	}
	return stale, nil
}

// Publish records version as published and brings the docs in line: what
// release.yml's docs job runs once a release is out. version needs a dated
// section, and a release older than the one recorded is refused, since the
// docs would then name an older release than the newest one out.
func Publish(root, changelog, version string) error {
	if version == unreleased {
		return fmt.Errorf("the Unreleased section is not a release")
	}
	if _, err := Latest(changelog); err != nil {
		return err
	}
	if _, err := Section(changelog, version); err != nil {
		return err
	}
	disk := fromDisk(root)
	if current, err := published(disk, changelog); err == nil && compareVersions(version, current) < 0 {
		return fmt.Errorf("%s records %s already; %s is older", Released, current, version)
	}
	// Regenerate against the new record first and write nothing unless
	// that succeeds, so a pin that no longer matches leaves the files as
	// they were rather than half moved.
	next := func(path string) (string, error) {
		if path == Released {
			return version + "\n", nil
		}
		return disk(path)
	}
	all, err := changes(next, changelog)
	if err != nil {
		return err
	}
	current, err := disk(Released)
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	return writeChanges(root, append(all, change{Released, current, version + "\n"}))
}

// Write brings the site's changelog page and every pin in line with the
// changelog and the published release, leaving a file that already matches
// untouched.
func Write(root, changelog string) error {
	all, err := changes(fromDisk(root), changelog)
	if err != nil {
		return err
	}
	return writeChanges(root, all)
}

// writeChanges writes each change whose file does not already hold it.
func writeChanges(root string, all []change) error {
	for _, c := range all {
		if c.current == c.want {
			continue
		}
		path := filepath.Join(root, filepath.FromSlash(c.file))
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil { //nolint:gosec // the site's docs directory, meant to be world-readable
			return err
		}
		if err := os.WriteFile(path, []byte(c.want), 0o644); err != nil { //nolint:gosec // a docs page in the repository, meant to be world-readable
			return err
		}
		fmt.Println("wrote", c.file)
	}
	return nil
}
